    // 충돌하더라도 그 프레임의 모든 장애물은 끝까지 움직입니다.
    if (!s.immune && s.obstacles.some(o => MINI.hit(player, { ...o, x: o.x - s.x + 180 }))) crash();
    this.anomaly = `중력 ${s.sign === 1 ? '↓ 바닥' : '↑ 천장'} · 충돌 ${s.deaths}회`;
    this.risk = Math.min(100, this.actions * 9);
